  var totalPerim = 6124.8;
  var DRAW_DURATION = 1900;
  var MIN_UNIT_DUR = 90;
  var OVERLAP = 1.5;

  var elems = UNITS.map(function(u) {
    var p = document.createElementNS(svgns, 'path');
    p.setAttribute('d', u.d);
    p.setAttribute('fill-rule', 'nonzero');
    p.setAttribute('class', 'stroke-unit');
    group.appendChild(p);
    var len = p.getTotalLength();
    p.style.strokeDasharray = len;
    p.style.strokeDashoffset = len;
    return { el: p, len: len, perim: u.perim };
  });

  function ease(t) { return t<0.5 ? 4*t*t*t : 1-Math.pow(-2*t+2,3)/2; }

  function animate(duration, onUpdate, onDone, delay) {
    delay = delay || 0;
    setTimeout(function() {
      var start = null;
      function step(ts) {
        if (!start) start = ts;
        var p = Math.min((ts-start)/duration, 1);
        onUpdate(ease(p));
        if (p < 1) requestAnimationFrame(step);
        else if (onDone) onDone();
      }
      requestAnimationFrame(step);
    }, delay);
  }

